export type SourceCustomBuildingProgram = typeof SOURCE_CUSTOM_BUILDING_IDENTITIES[number]['program'];
export function classifyCustomBuildingSource(source:SourceCustomBuildingIdentity) {
 if(source.mapRoles.includes('normalMap')&&source.normalMapType!==0)throw new Error('Custom normalMap requires captured TangentSpaceNormalMap type0');
 if(source.shaderHashBasis!==undefined&&source.shaderHashBasis!==SOURCE_CUSTOM_BUILDING_SHADER_BASIS)throw new Error('Unverified custom-building shader basis');
 for(const expected of SOURCE_CUSTOM_BUILDING_IDENTITIES)if(source.key===expected.key&&source.shaderHash===expected.hash&&source.shaderSha256===expected.sha256&&source.type===expected.type){
  if(!(expected.vertexColorModes as readonly boolean[]).includes(source.vertexColors)||!(expected.alphaTestModes as readonly boolean[]).includes(source.hasAlphaTest)||!expected.mapRoleSets.some(roles=>JSON.stringify([...roles].sort())===JSON.stringify([...source.mapRoles].sort())))throw new Error('Uncaptured custom-building renderer flags');
  return expected.program;
 }
 throw new Error(`Unsupported authored custom-building source ${source.key}`);
}
/** Common Standard base fields plus exact source glass uniforms for the tower branch. */
export function customBuildingParameterSchema(source:SourceCustomBuildingIdentity){
 const program=classifyCustomBuildingSource(source);
 const material={ base:[{name:'diffuse',size:3 as const},{name:'emissive',size:3 as const},...['opacity','emissiveIntensity','roughness','metalness','envMapIntensity','alphaTest'].map(name=>({name,size:1 as const}))],
  glass:program==='tower-glass'?[...['pgF0','pgRough','pgDirt','pgStW','pgBl','pgTr','pgSd','pgShr','pgGlow','pgSlk','pgLit'].map(name=>({name,size:1 as const})),{name:'pgBody',size:3 as const},{name:'pgRm',size:4 as const},{name:'pgOrg',size:3 as const}]:[] };
 return{program,material:[...material.base,...material.glass,...(source.mapRoles.includes('normalMap')?[{name:'normalScale',size:2 as const}]:[]),...(program==='self-lit'?[{name:'sourceDayNight',size:2 as const}]:[])],variant:[],frame:['source-world-position','source-world-normal']};
}

/** The source emits decimal literals via toFixed(3), which may differ from the cache key's raw JS floats. */
export function customBuildingSourceConstants(source:SourceCustomBuildingIdentity) {
 const program=classifyCustomBuildingSource(source);
 if(program!=='self-lit')return {};
 const record=SOURCE_CUSTOM_BUILDING_IDENTITIES.find(record=>record.key===source.key&&'sourceDayNight' in record);
 if(!record||!('sourceDayNight' in record))throw new Error('Missing recorded b3self coefficients');
 return {sourceDayNight:[...record.sourceDayNight]};
}
